class Solution:
    def sortColors(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        a = 0
        b = len(nums)-1
        c = 0

        while a<=b and c<=b:
            if nums[c]==0:
                nums[a],nums[c] = nums[c],nums[a]
                a+=1
                c+=1
            elif nums[c]==2:
                nums[c],nums[b] = nums[b],nums[c]
                b-=1
            else:
                c+=1

