class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        ans = 0
        i = 0
        j = 0 
        map = {}
        mx = 0
        n = len(s)
        while i<=j and j<n:
            if s[j] not in map:
                map[s[j]] = 1
            else:
                map[s[j]] += 1

            window = map.values()
            tm = max(window)
            sm = j-i+1

            while sm-tm>k and i<j:
                if map[s[i]] != 1:
                    map[s[i]] -= 1
                else:
                    del map[s[i]]
                i+=1
                window = map.values()
                tm = max(window)
                sm = j-i+1   

            if mx<=sm and sm-tm<=k:
                mx = sm
            j+=1


        return mx
